<?php
/** Proof — send (spec "Proof", 4): an internal article to an external requester → 422 "That article is internal."; a public one → a public reply with the link and summary, mailed, ticket.reply + article.send rows, article_links (sent); the registry marks the pauses; delete refused while sent. */
require __DIR__ . '/lib.php';
$W = world();
$owner = as_member(1); $marco = as_member(27);
$t = $W['t_jo2'];
$long = str_repeat('SMOKE The quick brown fox jumps over the lazy dog. ', 12);
[$pub, $pubSlug] = mk_article($owner, 'SMOKE How to reset a password', ['body' => $long, 'tags' => 'password']);
[$int, $intSlug] = mk_article($owner, 'SMOKE Internal reset procedure', ['visibility' => 'internal']);
[$draft] = mk_article($owner, 'SMOKE Unfinished', ['status' => 'draft']);
echo "1. Refusals\n";
[$c, $b] = act($marco, '/kb/admin/send.php', ['ticket' => $t, 'article' => $int]);
ok($c === 422 && msg($b) === 'That article is internal.', 'an internal article to an external requester: 422 "That article is internal."');
[$c, $b] = act($marco, '/kb/admin/send.php', ['ticket' => $t, 'article' => $draft]);
ok($c === 404, 'a draft cannot be sent (404 to a reader of the knowledge base)');
ok(act(as_member(26), '/kb/admin/send.php', ['ticket' => $t, 'article' => $pub])[0] === 404 && act(as_member(29), '/kb/admin/send.php', ['ticket' => $t, 'article' => $pub])[0] === 403, 'a requester who may not see the ticket: 404; a collaborator on it: 403');
echo "2. A public article\n";
$since = last_activity_id();
$before = count(outbox($t));
[$c, $b] = act($marco, '/kb/admin/send.php', ['ticket' => $t, 'article' => $pub, 'body' => 'SMOKE Jo, this should help:']);
$mid = (int) ($b['message_id'] ?? 0);
$m = q('SELECT * FROM messages WHERE id = :m', ['m' => $mid])[0] ?? null;
ok($c === 200 && $m !== null && $m['kind'] === 'public_reply' && (int) $m['author_member_id'] === 27, 'article_send: a public reply by Marco');
$summary = article_summary(['body_text' => $long], 300);
ok(str_starts_with($m['body_text'], "SMOKE Jo, this should help:\n\n") && str_contains($m['body_text'], 'SMOKE How to reset a password') && str_contains($m['body_text'], '/kb/' . $pubSlug) && str_contains($m['body_text'], $summary), 'the reply = the words, the title, the absolute link and the summary');
ok(mb_strlen($summary) <= 301 && str_ends_with($summary, '…') && !str_ends_with(rtrim($summary, '…'), ' '), 'the summary is cut at a word within 300 characters');
$ob = outbox($t);
ok(count($ob) === $before + 1 && end($ob)['kind'] === 'replied' && str_contains(end($ob)['body'], '/kb/' . $pubSlug), 'the requester is mailed the reply with the link (the outbox)');
ok(count(activity('ticket.reply', $since)) === 1 && count(activity('article.send', $since)) === 1 && json_decode(activity('article.send', $since)[0]['after'], true) == ['article_id' => $pub, 'message_id' => $mid] && (int) activity('article.send', $since)[0]['queue_id'] === $W['it'], 'ticket.reply and article.send logged (article_id, message_id; ticket and queue on the row)');
ok(count(links_of($t, 'sent')) === 1 && (int) links_of($t, 'sent')[0]['article_id'] === $pub, 'article_links (sent)');
ok(targets($t)['first_response']['met_at'] !== null, 'the first response is met');
echo "3. To a member requester, and the pauses\n";
marco_in_general();
[$c, $b] = act($marco, '/kb/admin/send.php', ['ticket' => $W['t_p1'], 'article' => $int]);
ok($c === 200 && count(links_of($W['t_p1'], 'sent')) === 1, 'an internal article goes to a member requester (the link needs their session)');
$reg = json_decode((string) file_get_contents(dirname(__DIR__, 3) . '/mcp/action_registry.json'), true);
$by = $reg['actions'] ?? [];
ok(str_contains(json_encode($by['article_send'] ?? []), 'external_send') && str_contains(json_encode($by['article_delete'] ?? []), 'deletion') && !str_contains(json_encode($by['article_suggest'] ?? []), 'external_send'), "the registry marks article_send external_send and article_delete deletion (the kernel's hook pauses an agent by key); article_suggest never pauses");
echo "4. Delete while sent\n";
[$c, $b] = act($owner, '/kb/admin/delete.php', ['article' => $pub]);
ok($c === 422 && msg($b) === 'This article was sent on 1 ticket — archive it instead.', 'delete refused while sent: "This article was sent on 1 ticket — archive it instead."');
[$c, $b] = act($owner, '/kb/admin/archive.php', ['article' => $pub]);
ok($c === 200 && article_row($pub)['status'] === 'archived' && req('GET', '/kb/' . $pubSlug)['code'] === 404, 'archived instead: gone from the public');
exit($GLOBALS['fails'] === 0 ? 0 : 1);
